import{_ as i,C as r,o as h,c as d,a3 as a,E as o}from"./chunks/framework.Ba39LDvt.js";const f=JSON.parse('{"title":"EDA 与设计方法学路线","description":"结合上科大编程、电路、优化与 VLSI 课程，学习自动化设计、算法评测与 AI4EDA。","frontmatter":{"title":"EDA 与设计方法学路线","description":"结合上科大编程、电路、优化与 VLSI 课程，学习自动化设计、算法评测与 AI4EDA。"},"headers":[],"relativePath":"map/eda.md","filePath":"map/eda.md","lastUpdated":1795513256000}'),s={name:"map/eda.md"};function n(l,t,c,E,u,g){const e=r("CourseTable");return h(),d("div",null,[t[0]||(t[0]=a('<h1 id="eda-与设计方法学路线" tabindex="-1">EDA 与设计方法学路线 <a class="header-anchor" href="#eda-与设计方法学路线" aria-label="Permalink to &quot;EDA 与设计方法学路线&quot;">​</a></h1><p>电子设计自动化（Electronic Design Automation，EDA）把芯片问题转成模型、算法与可运行的软件。它适合喜欢编程、数据结构、数学优化，又愿意理解电路约束的同学。会运行工具和会研究工具是两个层次：前者要把流程用对，后者还要解释算法为什么有效、在哪些条件下失效。</p><p>这条路线可以从数字实现切入，也可以走向模拟优化、验证或 AI 辅助设计。先熟悉一个完整问题，比一开始堆砌很多优化算法更重要。</p><h2 id="按学年安排主线" tabindex="-1">按学年安排主线 <a class="header-anchor" href="#按学年安排主线" aria-label="Permalink to &quot;按学年安排主线&quot;">​</a></h2><p>基础安排依据 2026 级 EE 培养方案；进阶选择结合 2026–2027 年度开课表，是建议而非统一培养要求。研究生课程的本科选修资格、具体开课学期与先修认定，以教务系统和大纲为准。</p><table tabindex="0"><thead><tr><th>学期</th><th>课程</th><th>为什么放在这里</th></tr></thead><tbody><tr><td>大一秋</td><td>SI100B；数学分析 I、线性代数</td><td>同时建立信息技术直觉与数学表达能力</td></tr><tr><td>大一春</td><td>EE111/EE111L；数学分析 II、物理 I</td><td>理解算法要服务的电路对象，而不只处理抽象图</td></tr><tr><td>大二秋或春</td><td>EE115B、EE115A、EE150；SI140A</td><td>数字逻辑、连续模型与概率知识服务不同 EDA 问题</td></tr><tr><td>大二春</td><td>CS100；之后补基本数据结构与算法</td><td>EE215A 明确要求编程、电路及基本数据结构算法，不能只会脚本调用</td></tr><tr><td>大三秋</td><td>EE113、EE113L</td><td>认识数字 IC 的物理约束和实现对象，选课前确认 <code>EE115</code> 先修写法</td></tr><tr><td>大三春</td><td>EE215A；按目标和负担选 EE291F 或 EE2210</td><td>EE215A 承接 CS100、EE111 与算法基础；后两门要求 EE113</td></tr><tr><td>大三暑期</td><td>关注 Cadence 暑期实训通知</td><td>如获准参加，用工程流程检验约束、日志与结果分析能力</td></tr><tr><td>大四或研究生阶段</td><td>按需选 SI231B、SI251</td><td>矩阵计算与凸优化有助于研究，但都须先满足各自数学先修</td></tr><tr><td>具备机器学习基础后的春季</td><td>SI365</td><td>官方先修列 EE115B、CS280、CS282，不是“会 Python 就能学”的无门槛课</td></tr></tbody></table>',6)),o(e,{codes:"CS100,EE111,EE115A,EE115B,SI140A,EE113,EE113L,EE215A,EE291F,EE2210,SI231B,SI251,CS280,SI365"}),t[1]||(t[1]=a('<div class="info custom-block"><p class="custom-block-title">组件不是全部先修课程清单</p><p>本站精选数据没有收录所有数学与计算机课程。例如 SI251 还列出 SI151A 先修，CS280 要求 CS182/CS282/CS181 至少一门，SI365 另要求 CS282；这些课程应在官方全表与教务系统中核对，不能因组件未显示而忽略。</p></div><h2 id="先做工具使用者-再理解工具内部" tabindex="-1">先做工具使用者，再理解工具内部 <a class="header-anchor" href="#先做工具使用者-再理解工具内部" aria-label="Permalink to &quot;先做工具使用者，再理解工具内部&quot;">​</a></h2><p>**第一步：跑通一个小设计。**理解输入 RTL、库、约束、输出网表与报告之间的关系；改变一个约束，观察时序、面积和布局是否按预期变化。运行失败时读日志定位首个真实错误，不要一味切换参数。</p><p>**第二步：选一个可以单独评测的子问题。**例如网表统计、图遍历、简单划分、放置代价或时序传播。明确输入输出、合法性条件、优化目标与基线，别一开始就试图替代整套商业工具。</p><p>**第三步：建立研究闭环。**用可复现的数据集和固定配置评测；同时报告解质量、运行时间、内存和失败案例。小规模例子改善，不代表大规模设计或最终签核结果也改善。</p><h2 id="ai4eda-要额外注意什么" tabindex="-1">AI4EDA 要额外注意什么 <a class="header-anchor" href="#ai4eda-要额外注意什么" aria-label="Permalink to &quot;AI4EDA 要额外注意什么&quot;">​</a></h2><p>用机器学习预测时延、拥塞或选择优化动作时，要检查训练和测试设计是否泄漏、是否只在熟悉分布中有效、生成结果是否合法。预测指标和物理实现收益不是一回事；模型训练与推理开销也应计入相应的比较边界。</p><p>如果目标是 AI 芯片设计，请同时学习 <a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/ai-hardware">AI 硬件路线资源</a>；如果目标是用 AI 改善设计工具，则还要深入问题结构与优化基线。两者不能仅凭“AI + 芯片”的名称混为一谈。</p><h2 id="校外补充资源" tabindex="-1">校外补充资源 <a class="header-anchor" href="#校外补充资源" aria-label="Permalink to &quot;校外补充资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/eda-algo">EDA 算法自学</a>：补数据结构、图算法、组合优化、数值方法与基准评测。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/digital">数字电路自学</a>：避免只懂算法却不理解网表、时序与逻辑等价。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/foundations">基础工具与数学</a>：重点掌握 Linux、Git、C/C++、Python 和构建自动化。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/eda/open-source">开源 EDA</a>：可从 <a href="https://yosyshq.net/yosys/" target="_blank" rel="noreferrer">Yosys</a> 与 <a href="https://theopenroadproject.org/" target="_blank" rel="noreferrer">OpenROAD</a> 观察实际软件结构；<a href="/shanghaitech-ic-wiki-dev.github.io/eda/commercial">商业 EDA</a> 用于理解产业流程和许可边界。</li></ul><h2 id="可进入的科研方向" tabindex="-1">可进入的科研方向 <a class="header-anchor" href="#可进入的科研方向" aria-label="Permalink to &quot;可进入的科研方向&quot;">​</a></h2><p>以 <a href="/shanghaitech-ic-wiki-dev.github.io/research/eda">EDA 与设计方法学</a> 为中心，交叉到 <a href="/shanghaitech-ic-wiki-dev.github.io/research/digital-vlsi">数字 VLSI</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/research/architecture">体系结构</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/research/analog-mixed">模拟与混合信号</a> 或 <a href="/shanghaitech-ic-wiki-dev.github.io/research/hardware-security">硬件安全</a>。选题时先问：优化对象是什么，合法性怎样定义，最终改善由哪份报告或实验支持？</p><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to &quot;实践建议&quot;">​</a></h2><ol><li><strong>维护可重复的一键流程</strong>：记录工具版本、输入、约束、随机种子和关键报告；不要提交许可证、PDK、私有 IP 或账号配置。</li><li><strong>复现一个小而完整的基线</strong>：再做明确的算法改动，不通过改变数据集、放宽约束或只保留成功样例来制造提升。</li><li><strong>围绕真实设计做竞赛</strong>：从 <a href="/shanghaitech-ic-wiki-dev.github.io/competitions/">竞赛导航</a> 查当届 EDA 题目和规则，确认数据许可与评测边界。</li><li><strong>借助系统项目理解工具需求</strong>：<a href="/shanghaitech-ic-wiki-dev.github.io/competitions/ysyx">一生一芯</a> 可以提供处理器设计语境，<a href="/shanghaitech-ic-wiki-dev.github.io/courses/cadence-summer">Cadence 暑期实训</a> 可以补工程实现流程；二者都不等于自动获得流片或商业工具权限。</li></ol><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/2833/list.htm" target="_blank" rel="noreferrer">学院本科生培养</a>：2026 级 EE 基础课程安排，依据官方本地摘录整理。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年开课表</a>：课程代码、季节、先修及研究生课程分类。</li><li><a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer">学院本硕博课程体系</a>。</li></ul>',16))])}const b=i(s,[["render",n]]);export{f as __pageData,b as default};
